BEGIN;
CREATE TABLE IF NOT EXISTS chapter.reading_progress_companions (book_id UUID NOT NULL REFERENCES chapter.books(id) ON DELETE CASCADE,reading_round INT NOT NULL CHECK(reading_round>=1),schema_version SMALLINT NOT NULL DEFAULT 1,main_thread JSONB NOT NULL DEFAULT '{}'::jsonb,converging JSONB NOT NULL DEFAULT '[]'::jsonb,open_threads JSONB NOT NULL DEFAULT '[]'::jsonb,carry_forward JSONB NOT NULL DEFAULT '[]'::jsonb,output_language TEXT NOT NULL CHECK(output_language IN ('vi','en')),sessions_covered INT NOT NULL DEFAULT 0,last_log_id UUID REFERENCES chapter.reading_log(id),last_log_date DATE,last_log_session INT,source_revision BIGINT NOT NULL DEFAULT 1,stale BOOLEAN NOT NULL DEFAULT FALSE,generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(book_id,reading_round));
CREATE INDEX IF NOT EXISTS idx_reading_progress_companions_book_round ON chapter.reading_progress_companions(book_id,reading_round);COMMIT;
